    body: "LMS（Learning Management System、学習管理システム）とは、教材の配信、課題の提出・回収・採点、学習履歴やテスト結果の記録・管理などを、オンライン上で一元的に行うためのシステムです。もともと大学教育やeラーニングの分野で発展してきましたが、近年は初等中等教育でも導入が広がっています。\n\n教師にとっては、児童生徒一人ひとりの学習の進捗状況や理解度を可視化しやすくなるという利点があり、児童生徒にとっては、自分のペースで教材に取り組んだり、過去の学習履歴を振り返ったりしやすくなるという利点があります。課題の提出状況や採点結果を自動的に集計できるため、教員の事務負担の軽減にもつながり、保護者への学習状況の情報共有にも活用されています。\n\nGIGAスクール構想による一人一台端末の整備が進んだことで、日本の小中高等学校でもLMSの活用が広がっており、教材配信の基盤にとどまらず、個別最適化学習や反転授業、ラーニングアナリティクスを支える情報基盤の一つとして重要視されるようになっています。",
