      "教師と学習者が離れた場所にいながら、通信技術を用いて同時双方向的に授業を行う教育形態のこと。過疎地や小規模校における教育機会の確保、専門性の高い授業の提供などを目的に活用が進んでいる。",
    body: "遠隔教育とは、教師と児童生徒が異なる場所にいる状態で、テレビ会議システムなどの情報通信技術を用いて同時双方向的に行う授業形態を指します。教材を録画・配信するオンデマンド型の学習とは明確に区別され、その場での質疑応答など、対面授業に近いやり取りが行える点が、大きな特徴となっています。\n\n日本では、過疎地域や離島の小規模校において、多様な科目の開設や専門性の高い授業の提供が難しいという課題に対応するため、高等学校を中心に他校の授業を同時配信する形の遠隔教育が導入されてきました。近年は、病気療養中の児童生徒や不登校児童生徒への学習機会の確保策としても、あわせて位置づけられています。\n\n文部科学省は遠隔授業の実施にあたっての留意事項を通知等で示しており、対面指導との組み合わせ方や、単位認定の考え方、通信環境の整備などが、実施上の重要な論点となっています。ハイブリッド型授業やオンライン学習とも密接に関連する概念であり、教員の確保が難しい地域における教育の質の維持にも、大きく貢献するものと期待されています。",
