    body: "授業目的公衆送信補償金制度とは、学校等の教育機関の教員が、授業の過程で必要と認められる限度において、他者の著作物をオンラインで児童生徒の端末に送信したり、授業支援システムにアップロードしたりする際に、個別に著作権者の許諾を得ることなく、指定された補償金を支払うことで、それらを利用できるようにする制度です。\n\n2018年5月の著作権法改正によって創設され、2020年4月28日に施行されました。新型コロナウイルス感染症の拡大による遠隔授業の急速な普及を踏まえ、2020年度に限り補償金額が特例的に無償とされた経緯があり、この制度に対する社会的な注目を大きく高めるきっかけともなりました。\n\n補償金は、文化庁長官から指定を受けた唯一の団体である一般社団法人授業目的公衆送信補償金等管理協会（SARTRAS）が、教育機関の設置者から一括して徴収し、権利者に分配する仕組みになっています。オンライン学習やデジタル教科書の活用が広がる中で、著作権教育とあわせて学校現場全体での正しい理解が、より一層求められています。",
