      "生まれたときからインターネットやデジタル機器が身近にあり、それらを自然に使いこなして育った世代を指す概念。",
    body: "デジタルネイティブとは、幼少期からインターネットやスマートフォン、タブレットなどのデジタル機器が日常生活に存在する環境で育ち、それらを特別な学習を要せず自然に使いこなす世代を指す言葉である。米国の教育学者マーク・プレンスキーが2001年の論文で提唱した概念とされ、デジタル技術に後から適応した世代を指す「デジタルイミグラント」と対比して用いられる。\n\n日本では、GIGAスクール構想以降に義務教育を受けた世代が典型的なデジタルネイティブとされ、タブレット端末での学習や動画・SNSを通じた情報収集に強い親和性を持つ一方、長文読解や紙媒体での学習経験の不足、情報の真偽を吟味する力の弱さなどが課題として指摘されることもある。教育現場では、この世代の特性を踏まえたうえで、単に機器操作に慣れているだけでなく、情報を批判的に読み解く力を育てる必要性が強調されている。\n\nなお、近年の研究では、デジタル機器に触れて育った世代が一律に高いICTスキルを持つわけではないとする指摘もあり、「デジタルネイティブ」を単純な世代区分として扱うことへの批判もある。学校教育においては、世代的な前提に頼るのではなく、情報活用能力や情報モラルを体系的に指導することの重要性が改めて認識されている。",
    relatedSlugs: ["digital-literacy", "joho-katsuyo-noryoku", "digital-citizenship"],
    isCanonical: true,
    tags: ["デジタルネイティブ", "プレンスキー", "情報活用能力"],
