    body: "プログラミング的思考とは、自分が意図する一連の活動を実現するために、どのような動きの組み合わせが必要であり、一つ一つの動きに対応した記号をどのように組み合わせたらよいか、記号の組み合わせをどのように改善していけばより意図した活動に近づくか、といった論理的に考えていく力を指す。文部科学省が2020年度から全面実施された小学校学習指導要領の解説において定義した用語で、国際的に広く使われる「コンピュテーショナル・シンキング」を日本の教育文脈に即して整理したものである。\n\n小学校プログラミング教育の目標は、特定のプログラミング言語の文法習得ではなく、この論理的思考力を各教科等の学習と関連づけながら育成することに置かれている。算数の図形の学習でLOGO的な操作を体験したり、理科でセンサーやモーターの制御を試したりするなど、教科の内容と組み合わせた指導が想定されており、情報の教科化とは異なる位置づけを持つ点が特徴である。\n\nプログラミング的思考は、コンピュータを使わない「アンプラグド」な活動でも育成可能とされ、身近な作業を手順に分解して考える活動などを通じて、低学年から段階的に養うことができるとされる。一方で、各教科での実践は教員の裁量に委ねられる部分が大きく、指導内容や評価方法の標準化が十分でないことが課題として指摘されている。",
    relatedSlugs: ["programming-education", "unplugged-programming", "coding-programming-chigai"],
    isCanonical: true,
    tags: ["プログラミング的思考", "プログラミング教育", "学習指導要領"],
