    body: "AIリテラシー教育とは、人工知能(AI)がどのような仕組みで動作し、どのような場面で有用かつどのような限界があるかを理解したうえで、AIを適切に判断・選択し、責任を持って活用する能力を育成する教育を指す。生成AIの急速な普及により、単にAIの是非を判断する「AI倫理教育」とは別に、AIの動作原理やデータとの関係、出力結果の検証方法など、より実践的な知識・スキルの育成が求められるようになった。\n\n文部科学省は「初等中等教育段階における生成AIの利活用に関するガイドライン」(2023年7月公表、その後複数回改訂)において、教員や児童生徒が生成AIの特性を理解した上で活用することの重要性を示しており、AIリテラシーの育成は情報活用能力の一部として位置づけられている。高等教育段階では、数理・データサイエンス・AI教育プログラム認定制度などを通じて、より専門的なAIリテラシーの涵養が進められている。\n\nAIリテラシー教育の実践は、AIが生成した文章や画像の真偽・妥当性を検証する活動、AIの判断に潜むバイアスを考察する活動など多岐にわたる。教科の枠を超えた横断的なテーマであるため、情報科や総合的な学習の時間だけでなく、各教科の中でも扱われつつあるが、教員自身のAIへの理解や指導経験の蓄積が追いついていない点が課題である。",
