    body: "オンデマンド授業とは、あらかじめ録画・収録された講義動画や教材を、学習者が指定された期間内であれば自分の都合の良い時間に視聴して学習を進める授業形態である。決まった時刻に教員と学習者がオンラインで同時双方向に接続する「同時双方向型(ライブ配信型)」の遠隔授業とは異なり、時間的な制約が少ない点が特徴で、社会人学生や就労と学業を両立する学生にとって受講しやすい形態とされる。\n\n日本の大学教育においては、大学設置基準上、メディアを利用して行う授業の一類型として位置づけられており、新型コロナウイルス感染症の拡大に伴う一斉休校・遠隔授業への移行(2020年前後)を契機に急速に普及した。厚生労働省や大学設置基準の関連規定では、オンデマンド型の授業であっても、教員による指導やインターネット等を通じた質疑応答の機会を確保することが求められている。\n\nオンデマンド授業は自学自習のペースを尊重できる一方、学習者同士の対話や即時的なフィードバックが得にくく、学習の継続には高い自己調整学習の能力が求められる。そのため実践においては、動画視聴後に小テストやディスカッション課題を課す、対面授業やライブ配信授業と組み合わせるブレンド型で運用するなど、学習効果を補完する工夫が広く行われている。",
