    body: "2020年2月から3月にかけて、新型コロナウイルス感染症の拡大防止のため、文部科学省は全国の小中高等学校等に対し一斉臨時休校を要請した。この結果、多くの学校で長期にわたり対面授業が実施できない状況が生じ、家庭学習の保障や学びの継続を目的として、オンライン授業や課題配信システムの活用が急速に模索されることとなった。しかし当時は1人1台端末や家庭の通信環境が十分に整っておらず、自治体間・家庭間でオンライン対応に大きな格差が生じた。\n\nこの経験を踏まえ、当初は2023年度までの整備を予定していたGIGAスクール構想の実施が大幅に前倒しされ、2020年度中に多くの自治体で1人1台端末とネットワーク環境の整備が完了した。あわせて、家庭にWi-Fi環境がない児童生徒向けのモバイルルーター貸与や、通信費補助といった支援策も講じられ、非常時における学びの保障とICT環境整備の関係が政策的に強く意識される契機となった。\n\nコロナ禍を経て、オンライン授業や動画教材の活用は平時の教育活動においても定着しつつあり、学級閉鎖時や不登校児童生徒への学習支援手段としても位置づけられるようになった。一方で、対面でのコミュニケーションや体験活動の重要性が改めて見直され、オンラインと対面をどのように組み合わせるかという議論は、コロナ禍収束後も教育のICT活用を考える上での重要な論点として残っている。",
