    body: "学校における個人情報保護とは、児童生徒の氏名や住所といった基本情報にとどまらず、成績、出欠、健康診断結果、指導要録、家庭の状況といった機微性の高い情報を、ICT環境の中でどのように適切に収集・保管・利用・廃棄するかに関する取り組みを指す。GIGAスクール構想による1人1台端末の普及や、校務支援システム・学習eポータルなどクラウドサービスの活用拡大により、扱われる教育データの量と種類が急増したことで、その保護の重要性が一段と高まっている。\n\n日本では個人情報保護法や、地方公共団体が定める個人情報保護条例に基づき、学校が保有する個人情報の取り扱いが規律される。文部科学省の「教育情報セキュリティポリシーに関するガイドライン」は、情報資産を重要度に応じて分類し、アクセス制御やログ管理、クラウドサービス利用時の契約条件の確認などを求めており、教育委員会や学校はこれに沿った運用体制の整備を進めている。\n\n実務上は、教員による個人情報を含む書類やUSBメモリの紛失、私物端末への無断保存、クラウドの設定不備による意図しない公開といったインシデントが後を絶たず、技術的対策だけでなく、教職員一人ひとりの情報リテラシーの向上が不可欠とされる。また、教育データの利活用が進む中で、保護者への説明責任やデータの二次利用に関する同意のあり方など、利活用と保護のバランスをどう取るかが継続的な論点となっている。",
