    body: "デジタルタトゥーとは、SNSやブログ、動画投稿サイトなどインターネット上に一度公開された個人の写真、発言、投稿内容が、本人が削除した後もコピーや転載、検索エンジンのキャッシュ等を通じて完全には消し去ることが難しく、半永久的に残り続けてしまう状態を、消すことのできない入れ墨(タトゥー)に例えて表現した用語である。学校教育における情報モラル教育・デジタルシティズンシップ教育の重要なテーマの一つとして取り上げられる。\n\n児童生徒がSNSに不用意に投稿した内容が、進学や就職の際に第三者に発見され不利益を被る事例や、軽率な投稿が炎上に発展し個人が特定・非難される事例が社会問題化してきた。教育現場では、一度発信した情報の拡散力と不可逆性を実感を伴って理解させるため、模擬的な情報拡散のシミュレーションや、実際の炎上事例の分析などを取り入れた授業が行われている。\n\nデジタルタトゥー問題への対応としては、投稿前に内容を吟味する習慣づけに加え、万一不適切な情報が拡散した場合の相談窓口(法務局の人権相談やプロバイダへの削除依頼制度など)についての知識を持たせることも重要とされる。忘れられる権利をめぐる法的な議論とも関連しており、情報モラル教育とインターネットガバナンスの両面から扱われるテーマである。",
