    body: "教育データ利活用ロードマップは、デジタル庁、総務省、文部科学省、経済産業省の4府省庁が連携して2022年1月に策定した文書であり、「誰もが、いつでもどこからでも、誰とでも、自分らしく学べる社会」の実現をミッションに掲げ、教育データの利活用に関する国の施策の全体像と工程を示したものである。データの「スコープ(範囲)」「品質」「組み合わせ」を充実・拡大させる3つの軸を設定している点が特徴である。\n\nロードマップでは、教育データの利活用の実現を短期・中期・長期の3フェーズに分け、2030年ごろの本格的な実現を見据えている。短期フェーズでは、教育現場を対象とした調査・手続のオンライン化、通信環境などインフラ面の阻害要因の解消、学習eポータルやMEXCBTなど教育データの基本項目・形式の標準化が進められた。中長期的には、学習系データと校務系データを統合的に分析し、エビデンスに基づく教育政策や指導改善に活用することが目指されている。\n\nロードマップに基づく取り組みは、学校現場での校務支援システムと学習系システムの連携、教育データ標準の整備など具体的な施策として展開されている。一方で、教育データの利活用には、個人情報保護やデータの二次利用に関する保護者の同意のあり方、自治体間のシステム互換性の確保など解決すべき課題も多く、継続的な制度設計の議論が行われている。",
