    body: "MEXCBT（メクビット）は、文部科学省が整備したオンライン学習・アセスメントのためのCBT（Computer Based Testing）システムである。正式名称は「学びの保障オンライン学習システム」で、コロナ禍における学びの保障と、海外で広がるCBT導入の動きを背景に、令和2年度から開発が進められた。\n\nプロトタイプ版は令和3年7月から10月にかけて約14万人の児童生徒が参加する実証研究で試用され、同年11月からは機能を拡充した版が希望する全国の小・中・高等学校等で順次利用できるようになった。国や自治体などが作成した問題を中心に掲載され、公開済みの全国学力・学習状況調査の問題やPISAの公開問題なども活用できる。利用の入口には学習eポータルが用いられ、シングルサインオンで接続する仕組みが取られている。\n\nMEXCBTは日常の学習や自治体独自の学力調査での活用を想定した基盤であり、全国学力・学習状況調査のCBT化の検討（2020年5月に専門のワーキンググループで検討開始）とも関連して語られる。調査のCBT化では項目反応理論（IRT）の活用方針も示されているが、実施教科や年度は更新されるため、最新の文部科学省資料で確認する必要がある。",
