    body: "平成30年告示の高等学校学習指導要領で、共通教科「情報」は「情報Ⅰ」「情報Ⅱ」の2科目に再編された。情報Ⅰは全ての生徒が履修する共通必履修科目で、2022年度（令和4年度）の入学生から年次進行で実施されている。これにより、プログラミングを含む情報教育が全員に保障される点が大きな特徴である。\n\n文部科学省の教員研修用資料によれば、情報Ⅰではプログラミング、モデル化とシミュレーション、情報通信ネットワークと情報セキュリティ、データベースの基礎、コンテンツ制作の基礎となる情報デザインなどを扱い、導入として情報モラルにも触れる。情報Ⅱは情報Ⅰを土台に、情報システム、多様なデータの活用、コンテンツの創造を深め、情報と情報技術を活用した問題発見・解決の探究を位置づけている。\n\n情報Ⅰは大学入学共通テストの出題科目にもなり、授業の質や教員の指導力、専任教員の確保が課題として論じられてきた。なお、次期学習指導要領に向けて情報Ⅰ・情報Ⅱの内容構成の見直しが検討されているとされるため、現行の細目は高等学校学習指導要領解説（情報編）で確認するとよい。",
