    body: "著作権教育には二つの側面がある。一つは教員自身が授業で他人の著作物を適切に利用するための知識であり、もう一つは児童生徒が創作者の権利を尊重し、自ら創作・発信する際のルールを学ぶ教育である。1人1台端末で写真・音楽・文章を手軽に扱えるようになった現在、後者は情報モラル教育の中核の一つとなっている。\n\n教員側の根拠となるのは著作権法の権利制限規定で、教育機関での複製や、授業目的の公衆送信（遠隔授業やLMSでの資料配信など）について、一定の条件のもとで許諾なしに利用できる仕組みが整備された。2018年の法改正により授業目的公衆送信補償金制度が設けられ、2020年に運用が始まっている（詳細は既存項目「授業目的公衆送信補償金制度」を参照）。\n\n児童生徒への指導では、引用の要件（主従関係、出典明示など）、他人の画像・文章の無断転載やSNS投稿の問題、生成AIが出力した内容と著作権の関係、学習成果物の著作権の扱いなどを、具体的な場面に即して学ばせる。文化庁は学校向けの解説資料を公開しており、最新の運用指針はそちらで確認する必要がある。",
