    body: "1人1台端末では、数百〜数万台の端末を学校や教員が手作業で管理することは現実的でないため、MDM（モバイル端末管理）の導入がほぼ前提となる。MDMでは、アプリの一括配信、機能やアプリの制限、校内Wi-Fiへの自動接続、OSの更新タイミングの管理、紛失・盗難時の遠隔ロックなどを行う。導入にあたっては、GIGAスクール構想の標準仕様に沿った製品選定が行われてきた。\n\nフィルタリングは、不適切なサイトの閲覧やフィッシングサイトへの接続を防ぐ仕組みである。従来の「許可リスト方式」は登録の運用負担が大きく、持ち帰り学習への対応も難しいとされるため、カテゴリ判定やクラウド型サービスを組み合わせる例が見られる。学校・学年ごとに異なる設定が必要になる点も、一般企業と異なる配慮事項である。\n\n一方、制限を強めすぎると探究的な活用を妨げるため、情報モラル教育と併せて、児童生徒が自ら判断できる力を育てる視点が重要とされる。運用は教育情報セキュリティポリシーに基づいて設計され、具体的な設定は自治体ごとに異なる。",
