    body: "SAMRモデルは、教育における技術の活用の深まりを、Substitution（代替）、Augmentation（拡大）、Modification（変容）、Redefinition（再定義）の4段階で整理する枠組みである。米国の研究者ルーベン・プエンテデューラが提唱し、2010年前後から広く知られるようになった。\n\n代替は従来の道具を技術に置き換えるだけの段階（板書を電子黒板に置き換えるなど）、拡大は機能面で改善が加わる段階である。変容は授業のデザインそのものが大きく見直される段階、再定義はこれまで不可能だった新しい学習課題が可能になる段階とされる。前半2段階は既存の授業の改善、後半2段階は授業の構造の変革として区別されることがある。\n\n授業実践を自己点検する視点として有用な一方、段階が上であるほど良いとは限らず、代替段階の活用にも意義がある。また、理論的基盤の弱さや実証研究の不足を指摘する研究もあるため、評価ツールではなく省察の手がかりとして用いることが望ましい。TPACKなど教師の知識に注目するモデルと併用されることも多い。",
