    body: "TPACK（Technological Pedagogical Content Knowledge、技術的・教育的・内容的知識）は、教師がICTを効果的に授業へ統合するために必要な知識を示すモデルである。出発点は、リー・シュルマンが1986年に提唱したPCK（教科内容に即した教授法の知識）で、パンヤ・ミシュラとマシュー・コーラーが2006年の論文（Teachers College Record掲載）で技術に関する知識を加えて再検討した。\n\nモデルは、内容知識（CK）、教授法知識（PK）、技術知識（TK）の3領域と、その重なり（PCK、TCK、TPK、そして中心のTPACK）で構成される。技術を教科内容や教授法と切り離して扱うのではなく、三者の関係と制約の中で授業を設計する点が特徴である。当初のTPCKという呼称は、のちにTPACKへ改められた。\n\n教員養成や研修でICT活用指導力を考える際の枠組みとして用いられ、操作研修だけでは不十分で、教科の目標に即した活用設計が重要であることを示す。SAMRモデルが活用の段階に注目するのに対し、TPACKは教師が持つべき知識に注目する点で補完的である。",
