    body: "オープンバッジは、学習や活動の成果を示すデジタルバッジに、発行者・取得内容・取得基準などのメタデータを埋め込み、真正性を検証できるようにした仕組みである。国際標準規格は教育技術の標準化団体1EdTech（旧IMS Global）が策定しており、2024年に公開されたOpen Badges 3.0では、受領者が自分のウォレットで管理できる点などが特徴とされる。\n\n日本の大学でも活用が広がり、東京理科大学は2023年度から教育・研究・課外活動の取組に発行している。立命館大学は教員向けFDプログラムの修了をマイクロクレデンシャルとして認定する形に再設計しオープンバッジを発行し、関西大学は大学院プログラムの修了者向けにOpen Badges 3.0準拠のデジタル証明書を発行する取組を進めている。小さな単位の学びを可視化できることから、リカレント教育との親和性が高い。\n\n課題は、バッジの信頼性や社会的通用性の確保、発行基準の質保証、学習履歴データの取扱い（個人情報保護）である。学習歴を可視化する仕組みとして、eポートフォリオや学習ログの活用とも関連して論じられる。",
