    body: "数理・データサイエンス・AI教育プログラム認定制度は、大学・高等専門学校等が正規課程で提供する数理・データサイエンス・AI教育のうち、一定の要件を満たすものを文部科学大臣が認定して奨励する制度である。実施要綱は2021年（令和3年）2月に決定され、令和3年度から実施されている。AI戦略で掲げられた、全ての大学・高専生が数理・データサイエンス・AIの基礎を学ぶという方針を具体化するものである。\n\nレベルは、基礎的な能力を育成する「リテラシーレベル」と、自らの専門分野で課題解決に活用する実践的能力を育成する「応用基礎レベル」の二つ。応用基礎レベルは2022年度から認定が始まり、認定されたプログラムのうち先導的で独自の工夫・特色を持つものは「プラス」に選定される。内閣府の資料では、応用基礎レベルの認定数は2025年8月時点で366件とされる。認定には有効期限があり、更新が必要である。\n\n大学にとっては教育内容の質保証と学生へのアピールになる一方、認定の有無が教育の実質を表すわけではなく、実際の学修成果の検証が課題となる。初等中等教育の情報Ⅰ・データサイエンス教育からの接続も意識され、今後の動向は文部科学省の最新資料で確認する必要がある。",
