    body: "「教育の情報化に関する手引」は、文部科学省が教育委員会や学校向けに、教育の情報化の進め方をまとめた解説書である。小学校学習指導要領（平成29年告示）の令和2年4月からの実施を前に、令和元年（2019年）12月に公表された。\n\nその後、GIGAスクール構想の進展や環境整備関連予算の具体化を受けて、2020年6月に追補版が出された。追補版では時点の更新やイラストの追加が行われ、ICT活用の学習場面を分類した10の分類例のイラスト、特別支援教育でのICT活用場面、遠隔教育に関する著作権法改正（授業目的公衆送信補償金制度）などが盛り込まれた。\n\n内容は、情報教育（プログラミング教育や情報モラルを含む）、教科指導におけるICT活用、校務の情報化、教員のICT活用指導力、学校のICT環境整備、情報セキュリティなど広範囲にわたる。文部科学省は教育情報セキュリティポリシーに関するガイドライン等も別途示しているため、実務では手引と各種ガイドラインの最新版を併せて確認する必要がある。",
