    body: "フィルターバブルは、アルゴリズムが利用者の検索履歴や閲覧傾向に合わせて情報を選別した結果、自分が好む情報ばかりに囲まれ、異なる意見や事実が見えにくくなる現象である。インターネット活動家イーライ・パリサーが2011年の著書『The Filter Bubble』（邦題『閉じこもるインターネット』）で論じたことで広まった。\n\nエコーチェンバーは、SNS等で似た意見を持つ人々が集まり、同じ意見が繰り返し反響して強まっていく状態を指す。フィルターバブルが主にシステムによる情報の入口の偏りであるのに対し、エコーチェンバーは人間関係の中での意見の増幅という違いで整理されることが多い。両者は重なり合って、フェイクニュースや偽情報の拡散を助長しうる。\n\n教育では、これらの仕組みを知り、複数の情報源を比較する、情報の出所や日付を確認する、異なる立場の意見に触れるといった習慣を育てる学習が行われる。メディア・リテラシーやフェイクニュース対策と合わせて扱うことが効果的とされるが、現象の実際の影響の大きさは研究によって見解が分かれるため、断定せず学ばせる姿勢が望ましい。",
    relatedSlugs: ["media-literacy", "disinformation-kyoiku", "digital-citizenship", "digital-literacy"],
