    body: "1人1台端末の日常的利活用とは、GIGAスクール構想により児童生徒に配備された情報端末を、従来の鉛筆やノートと同様の文房具として恒常的に使いこなす教育実践である。特別なICT授業だけでなく、すべての教科や学校生活のあらゆる場面で道具として自然に浸透させることが政策的にも求められている。\n\n学校現場では、朝の健康観察や連絡帳機能から始まり、授業中の調べ学習、意見の書き込み、小テストの解答やまとめノートの作成まで幅広く活用される。教員からの一方的な指示を待つのではなく、児童生徒が自らの判断で画面を開き、必要な情報を検索・集約する環境を日常的に整える。\n\n文房具としての定着は、自らのペースで学びを進める個別最適な学びと、互いの考えを共有して深め合う協働的な学びを一体的に促進する。端末の適切な取扱い習慣や健康への配慮、情報モラルを体得させながら、生涯にわたり学び続ける自律的な資質・能力を育む基礎となる。",
