    body: "デジタルワークシートの配布・回収・採点とは、授業支援システムやクラウドを活用し、従来の紙のワークシートをデジタル形式で一括送受信・処理する教育手法である。GIGAスクール構想における教育環境の高度化と、教員の働き方改革を同時に推進する基幹技術として定着している。\n\n授業開始時、教員は作成した課題データをクリック1つで全生徒端末へ瞬時に配信し、生徒は手書きペンやキーボードで解答を書き込む。提出期限に自動回収されたシートに対し、教員は一覧画面から素早く丸付けやコメントを行い、即座に生徒の手元へ返却して復習を促す。\n\n回収や採点の即時化により、学習直後の効果的な指導が可能となり、児童生徒の理解度に応じたきめ細かな形成的評価が実現する。印刷や配架にかかる物理的な手間を大幅に削減し、児童生徒と向き合う時間を創出するとともに、学習履歴のデジタル管理を容易にする。",
