    body: "教育現場における生成AIの利活用が進む中、児童生徒や教職員の個人情報保護と他者の著作権保護は重大な規範課題である。文部科学省の利用指針でも、機密情報や個人の特定につながる情報の入力防止と、著作権法の範囲を踏まえた適切な利用が強く求められている。\n\n学校での実践では、指示文に氏名や成績、写真などの個人情報を絶対に入力しない設定や指導を徹底する。また、AIが生成した文章や画像を授業教材や創作物に利用する際は、既存の著作物との類似性や依拠性に留意し、出典の明記や利用規約の遵守を組織的に確認する。\n\n情報技術の利便性を享受しつつリスクを正しく見極める態度は、個別最適な学びを安全に深める基礎となる。児童生徒が自ら規約や権利関係を意識して適切にツールを使いこなす力を育成し、デジタル社会を主体的に生き抜く確かな情報モラルを定着させることが期待される。",
